import glob, re
for p in glob.glob('de/rub/nds/tlsattacker/core/quic/frame/*.java'):
    s=open(p).read(); o=s
    # convert remaining int-taking setters of modifiable fields to long
    def repl(m):
        return "public void set%s(long %s) {"%(m.group(1),m.group(2))
    s=re.sub(r"public void set(\w+)\(int (\w+)\) \{", repl, s)
    s=s.replace("(long) streamId)","streamId)").replace("(long) offset)","offset)").replace("(long) length)","length)")
    s=re.sub(r"safelySetValue\(this\.(\w+), \(long\) \1\)", r"safelySetValue(this.\1, \1)", s)
    if s!=o: open(p,'w').write(s); print('setter widened',p)
PYEOF
